"""Writes .github/workflows/mpvfx-macos-source.yml from mpvfx-macos.yml: the same macOS jobs, called only by
OneTake-app/OneTake-actionRunners-1 on a named oneTake commit, so they run on that organization's runner pool.

The generated file differs from its source in exactly these ways, and nothing else:
  - its only trigger is workflow_call, with required inputs source_repository and source_ref (no schedule, no
    dispatch, no caller in this repository), so no default-branch run here ever builds a commit an input chose;
  - every checkout takes that repository and commit and keeps no token (persist-credentials: false);
  - no cache step (a lookup of one reads as a miss): those runs share the runners repository's default-branch
    cache scope, where a labelled pull request could otherwise plant a build cache that a later nightly (whose disk
    image is published) restores;
  - no secret: the disk image is always ad-hoc signed (notarization is for stable tags, built in this repository);
  - the build number is the source commit.

  python3 -I -B .github/ci/macos_source_workflow.py          rewrite the file
  python3 -I -B .github/ci/macos_source_workflow.py --check  fail when the file is not what this script writes
"""
import os
import re
import sys

import yaml

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
SOURCE = os.path.join(ROOT, ".github", "workflows", "mpvfx-macos.yml")
TARGET = os.path.join(ROOT, ".github", "workflows", "mpvfx-macos-source.yml")
HEADER = """\
# GENERATED by .github/ci/macos_source_workflow.py from mpvfx-macos.yml: do not edit; change the source and rerun it.
# Called only by OneTake-app/OneTake-actionRunners-1 (onetake-macos.yml) to build a oneTake commit on that
# organization's runners: no caches, no secrets, no token left in the checkouts (see the script for why).
"""
CHECKOUT = "actions/checkout@"
CACHE = "actions/cache/"


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper, value):
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


_Dumper.add_representer(str, _str)


HIT = re.compile(r"\$\{\{ steps\.[\w-]+\.outputs\.cache-hit \}\}")


def _step(step):
    uses = step.get("uses", "")
    if uses.startswith(CACHE):
        return None
    step = dict(step)
    if uses.startswith(CHECKOUT):
        step["with"] = {**step.get("with", {}), "repository": "${{ inputs.source_repository }}",
                        "ref": "${{ inputs.source_ref }}", "persist-credentials": False}
    env = step.get("env")
    if env:
        # No secret, and every removed cache lookup reads as a miss (each shard runs).
        step["env"] = {k: ("" if isinstance(v, str) and "secrets." in v else HIT.sub("false", v) if isinstance(v, str)
                           else v) for k, v in env.items()}
        if "MPVFX_BUILD" in env:
            step["env"]["MPVFX_BUILD"] = "${{ inputs.source_ref }}"
    return step


PIN = re.compile(r"uses: (\S+@[0-9a-f]{40})\s*(#.*)$")


def _pin_comments(source, text):
    """Puts back each pinned action's `# vX.Y.Z` comment, which the YAML writer drops."""
    comments = dict(m.groups() for m in map(PIN.search, source.splitlines()) if m)

    def add(match):
        return f"{match.group(0)} {comments.get(match.group(1), '')}".rstrip()

    return "\n".join(re.sub(r"uses: (\S+@[0-9a-f]{40})$", add, line) for line in text.split("\n"))


def generate(source):
    wf = yaml.safe_load(source)
    call = wf[True]["workflow_call"]
    inputs = dict(call.get("inputs", {}))
    inputs["source_repository"] = {"type": "string", "required": True}
    inputs["source_ref"] = {"type": "string", "required": True}
    out = {"name": "mpvfx-macos-source", "on": {"workflow_call": {"inputs": inputs}},
           "permissions": wf["permissions"], "env": wf.get("env", {}), "jobs": {}}
    for name, job in wf["jobs"].items():
        job = dict(job)
        job["steps"] = [s for s in (_step(s) for s in job["steps"]) if s is not None]
        out["jobs"][name] = job
    text = yaml.dump(out, Dumper=_Dumper, sort_keys=False, width=10**6, allow_unicode=True)
    return HEADER + _pin_comments(source, text)


def main(argv):
    with open(SOURCE, encoding="utf-8") as f:
        text = generate(f.read())
    if "--check" in argv:
        with open(TARGET, encoding="utf-8") as f:
            if f.read() != text:
                print("mpvfx-macos-source.yml is stale: run python3 -I -B .github/ci/macos_source_workflow.py")
                return 1
        return 0
    with open(TARGET, "w", encoding="utf-8") as f:
        f.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
